export const allCategories = categories

export const getProductBySlug = (slug) => allProducts.find(p => p.slug === slug)
export const getProductsByCategory = (cat) => allProducts.filter(p => p.categorySlug === cat)
export const getRelatedProducts = (slug, limit = 4) => {
  const product = getProductBySlug(slug)
  if (!product) return []
  return allProducts.filter(p => p.categorySlug === product.categorySlug && p.slug !== slug).slice(0, limit)
}
export const getFeaturedProducts = () => allProducts.filter(p => p.isFeatured)
export const getFilterTypes = (cat) => ['All', ...new Set(allProducts.filter(p => p.categorySlug === cat).map(p => p.tag))]
